import{_ as e,c as o,o as l,aj as r}from"./chunks/framework.B5VMNd4r.js";const p=JSON.parse('{"title":"第5章：金钱的盲区——关于钱，大脑撒过的那些谎","description":"","frontmatter":{},"headers":[],"relativePath":"handbook/user-cognition/chapter_5.md","filePath":"handbook/user-cognition/chapter_5.md","lastUpdated":1783615807000}'),n={name:"handbook/user-cognition/chapter_5.md"};function a(s,t,i,d,u,g){return l(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="第5章-金钱的盲区——关于钱-大脑撒过的那些谎" tabindex="-1">第5章：金钱的盲区——关于钱，大脑撒过的那些谎 <a class="header-anchor" href="#第5章-金钱的盲区——关于钱-大脑撒过的那些谎" aria-label="Permalink to “第5章：金钱的盲区——关于钱，大脑撒过的那些谎”">​</a></h1><p>你有没有经历过这些场景：</p><ul><li>投资亏损了，死扛着不卖，心想&quot;只要不卖就不算真的亏损&quot;——结果亏了更多</li><li>看到两只股票，一只涨了30%，一只跌了30%，觉得&quot;跌的那只更值得买，因为之前涨的已经贵了&quot;——其实两只完全无关</li><li>开会时所有人都同意一个方案，你心里有异议但没说，因为&quot;大家都没意见&quot;——结果方案失败了</li></ul><p>这些场景，都有一个共同的名字：<strong>金钱认知偏差</strong>。</p><p><strong>我是怕浪猫。</strong> 金钱偏差可能是整个系列中最&quot;贵&quot;的一类——因为它们每一次发作，都直接烧的是你的钱。但好消息是，一旦你认识了它们，就能在关键时刻识别并打断偏差链条。</p><p>这一章拆解<strong>6个与金钱和群体决策相关的认知偏差</strong>，每个都有直接对应的财务决策场景。文章结尾有6个偏差的完整对照表和决策检查清单，建议收藏。</p><hr><h2 id="_5-1-团体迷思——会议室里最危险的一种声音-共识" tabindex="-1">5.1 团体迷思——会议室里最危险的一种声音：共识 <a class="header-anchor" href="#_5-1-团体迷思——会议室里最危险的一种声音-共识" aria-label="Permalink to “5.1 团体迷思——会议室里最危险的一种声音：共识”">​</a></h2><p><strong>团体迷思</strong>（Groupthink）：<strong>为了在群体中保持和谐一致，避免冲突，我们会做出非理性决策。</strong></p><p>这个概念由心理学家Irving Janis在1972年提出，专门用来解释为什么聪明的团队会做出灾难性的集体决策。</p><p>最著名的案例是美国猪湾事件（Bay of Pigs）：1961年，肯尼迪政府批准了对古巴的入侵计划，情报界普遍认为成功概率很高。但回头看，有大量内部异议被压制了——因为团队成员不想在关键问题上挑战团队共识。</p><div style="margin:24px 0;padding:24px;background:#f6f6f6;border-radius:8px;text-align:center;color:#888;"><em>图：团体迷思：团队决策中异议被压制的机制</em></div><p><strong>团体迷思的8个典型症状（Janis原始模型）：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">症状</th><th style="text-align:left;">表现</th></tr></thead><tbody><tr><td style="text-align:left;">无懈可击的错觉</td><td style="text-align:left;">团队过度自信，认为自己的计划万无一失</td></tr><tr><td style="text-align:left;">集体合理化</td><td style="text-align:left;">对警告信号进行集体合理化，而非重新评估</td></tr><tr><td style="text-align:left;">对外部成员的质疑</td><td style="text-align:left;">团队将不同意见者视为&quot;不了解情况&quot;</td></tr><tr><td style="text-align:left;">自我审查</td><td style="text-align:left;">成员自我压制异议：&quot;既然大家都没意见……&quot;</td></tr><tr><td style="text-align:left;">一致性的压力</td><td style="text-align:left;">直接表达异议会承受社会压力</td></tr><tr><td style="text-align:left;">心灵守护者</td><td style="text-align:left;">团队指定成员专门负责&quot;防止负面信息干扰团队&quot;</td></tr><tr><td style="text-align:left;">全票通过倾向</td><td style="text-align:left;">决策过程中很少有正式投票，实际是隐性全票通过</td></tr><tr><td style="text-align:left;">对异议者施压</td><td style="text-align:left;">对提出质疑的成员进行公开或隐性的压力</td></tr></tbody></table><p><strong>团体迷思在个人财务管理中的版本：</strong></p><p>你可能觉得团体迷思只发生在公司董事会，但实际上它的个人版本每天都在发生：</p><ul><li><strong>家庭财务决策：</strong> 家庭成员讨论要不要买房，所有人都在讨论&quot;买了以后怎么装修&quot;，没有人讨论&quot;如果房价下跌怎么办&quot;——因为讨论下跌意味着&quot;反对买房&quot;，而这在情绪上很难开口</li><li><strong>投资俱乐部：</strong> 几个人一起讨论股票，所有人都在讨论&quot;为什么这只股票好&quot;——因为加入讨论的人大多是认可这只股票才会参与的</li></ul><p><strong>打破团体迷思的方法：</strong></p><ol><li><strong>指定红队（Red Team）：</strong> 在每次重大决策中，指定一个人专门负责&quot;唱反调&quot;</li><li><strong>匿名意见收集：</strong> 在正式讨论前，匿名收集每个人的真实意见——口头讨论的社会压力太大</li><li><strong>&quot;反对票&quot;机制：</strong> 强制要求每个重大决策有人提出反对意见，否则决策无效</li></ol><blockquote><p><strong>团体迷思的代价：</strong> 不是&quot;做了错误决定&quot;，而是&quot;没有做任何人在独自思考时会做的正确决定&quot;。</p></blockquote><hr><h2 id="_5-2-聚光灯效应——没有那么多人真正在意你" tabindex="-1">5.2 聚光灯效应——没有那么多人真正在意你 <a class="header-anchor" href="#_5-2-聚光灯效应——没有那么多人真正在意你" aria-label="Permalink to “5.2 聚光灯效应——没有那么多人真正在意你”">​</a></h2><p><strong>聚光灯效应</strong>（Spotlight Effect）：<strong>会高估他人对自己外表及行为举止的关注程度。</strong></p><p>心理学家Thomas Gilovich的实验证实了这一点：他让大学生穿上Barry Manilow（一位在当时被认为是&quot;过时&quot;的歌手）的T恤进入其他学生群体，然后问穿T恤的学生有多少人注意到了T恤——估计约50%的人会注意到。实际注意到的人数：约23%。而没穿T恤的学生高估得更多——他们估计约62%的人都注意到了。</p><div style="margin:24px 0;padding:24px;background:#f6f6f6;border-radius:8px;text-align:center;color:#888;"><em>图：聚光灯效应：实际关注度vs感知关注度的差距</em></div><p><strong>聚光灯效应在消费和金钱决策中的表现：</strong></p><ul><li><strong>炫耀性消费：</strong> 买名牌包、买豪车，部分动机是&quot;别人会注意到我&quot;——但实际上大多数人根本不关注你穿什么开什么</li><li><strong>社交媒体发帖：</strong> 发布前反复编辑，担心&quot;大家会怎么看&quot;——实际上没人在意，只有你自己在意</li><li><strong>&quot;丢人&quot;的决策：</strong> 拒绝朋友提出的高消费活动，因为&quot;如果不参加，大家会怎么看我&quot;——实际上大多数朋友根本不在乎</li></ul><p><strong>聚光灯效应的财务含义：</strong></p><p>聚光灯效应解释了为什么很多人把钱花在了&quot;展示性消费&quot;而非&quot;实际价值&quot;上——因为他们过高估计了这些消费的&quot;社会回报&quot;。而这些钱，完全可以用于更有长期价值的投资。</p><p><strong>如何对冲聚光灯效应：</strong></p><p>当你为&quot;别人会怎么看我&quot;而纠结消费时，问自己一个简单问题：&quot;我最近一次注意到朋友穿了什么、背了什么包，是什么时候？&quot; 大多数时候你会发现：你根本不记得朋友的外在消费——但你却觉得朋友在时刻注意你的。</p><hr><h2 id="_5-3-幼稚的愤世嫉俗——过度解读他人动机的陷阱" tabindex="-1">5.3 幼稚的愤世嫉俗——过度解读他人动机的陷阱 <a class="header-anchor" href="#_5-3-幼稚的愤世嫉俗——过度解读他人动机的陷阱" aria-label="Permalink to “5.3 幼稚的愤世嫉俗——过度解读他人动机的陷阱”">​</a></h2><p><strong>幼稚的愤世嫉俗</strong>（Naive Cynicism）：<strong>相信自己观察到的就是客观现实；而其他人则都是更加以自我为中心且有所图谋的。</strong></p><p>这个偏差与朴素实在论（Naive Realism）是一对：朴素实在论让我们觉得&quot;我的判断是客观的，别人是不理性的&quot;；幼稚的愤世嫉俗则让我们觉得&quot;别人的行为都是自私的，只有我的行为有其他动机&quot;。</p><div style="margin:24px 0;padding:24px;background:#f6f6f6;border-radius:8px;text-align:center;color:#888;"><em>图：幼稚的愤世嫉俗：他人行为vs自我行为的动机归因差异</em></div><p><strong>幼稚的愤世嫉俗在商业和谈判中的表现：</strong></p><ul><li>谈判桌上，对方提出一个方案，你立刻认为&quot;他肯定有自己的图谋&quot;——但实际上对方可能只是单纯地想达成合作</li><li>职场中，同事主动帮忙，你觉得&quot;他肯定想讨好领导&quot;——但也许人家只是友善</li><li>商家让利促销，你认为&quot;肯定是因为东西不好才促销&quot;——但实际上可能只是正常的库存管理</li></ul><p><strong>幼稚的愤世嫉俗的财务后果：</strong></p><p>这个偏差让你倾向于&quot;把人往坏处想&quot;，导致：</p><ul><li>在应该合作时拒绝合作（错失机会）</li><li>在应该信任时拒绝信任（交易成本增加）</li><li>在应该感谢时误解对方善意（破坏关系）</li></ul><p><strong>如何矫正幼稚的愤世嫉俗：</strong></p><p>在每次对他人动机做出判断之前，尝试列出至少三个可能的动机——不要只列出那个最愤世嫉俗的解释。一个更平衡的框架会让你看到：大多数人的行为是混合动机的，既不完全无私，也不完全自私。</p><hr><h2 id="_5-4-效用层叠——一个信念如何在社会中滚成大雪球" tabindex="-1">5.4 效用层叠——一个信念如何在社会中滚成大雪球 <a class="header-anchor" href="#_5-4-效用层叠——一个信念如何在社会中滚成大雪球" aria-label="Permalink to “5.4 效用层叠——一个信念如何在社会中滚成大雪球”">​</a></h2><p><strong>效用层叠</strong>（Availability Cascade）：<strong>集体信念会通过公众讨论和媒体报道而变得更加极端，最终变成&quot;公认的常识&quot;——即使它最初只是一个不完整的观察。</strong></p><p>这个概念由Cass Sunstein提出，描述了一个社会心理学机制：<strong>一件事越被讨论，它就显得越重要；它越显得重要，就有更多人讨论它——这是一个自我强化的循环。</strong></p><div style="margin:24px 0;padding:24px;background:#f6f6f6;border-radius:8px;text-align:center;color:#888;"><em>图：效用层叠：单一事件如何通过媒体放大变成社会共识</em></div><p><strong>效用层叠的经典案例：</strong></p><ul><li><strong>Alar恐慌（1989年）：</strong> 一种被用于苹果的合法生长调节剂被媒体报道为&quot;致癌物&quot;，引发了全国性恐慌，导致数亿美元的苹果产业损失。后来证明实际风险极低——但恐慌已经造成实质损害。</li><li><strong>次贷危机前：</strong> 房价持续上涨的叙事通过媒体报道不断强化，越来越多人相信&quot;房价永远只涨不跌&quot;，于是更多人投入房地产市场，最终制造了泡沫。</li></ul><p><strong>效用层叠在投资中的危害：</strong></p><p>一只股票因为某个事件成为了媒体热点，效用层叠效应会让它的&quot;重要性&quot;远超实际价值。投资者被舆论裹挟涌入，推高股价，形成泡沫——直到基本面最终发挥作用，泡沫破裂。</p><p><strong>识别效用层叠的信号：</strong></p><ul><li>一个话题突然出现在所有媒体上，但缺乏实质性的新信息</li><li>社交媒体上关于某话题的情绪化讨论显著增加</li><li>官方机构或专家开始&quot;不得不&quot;对这一话题发表声明</li></ul><p><strong>如何不被效用层叠裹挟：</strong></p><p>每次遇到&quot;全网都在讨论X&quot;的情况，先问自己：我现在知道的关于X的信息，有多少是基于原始数据，有多少是基于&quot;别人也在讨论X&quot;这个事实？如果答案是后者，你可能正处于效用层叠之中。</p><hr><h2 id="_5-5-零风险偏好——为什么人们宁可少赚也不愿冒险" tabindex="-1">5.5 零风险偏好——为什么人们宁可少赚也不愿冒险 <a class="header-anchor" href="#_5-5-零风险偏好——为什么人们宁可少赚也不愿冒险" aria-label="Permalink to “5.5 零风险偏好——为什么人们宁可少赚也不愿冒险”">​</a></h2><p><strong>零风险偏好</strong>（Zero-Risk Bias）：<strong>倾向于要把小的风险降为零，而不是选择可以减少更多整体风险的另一种方案。</strong></p><p>行为经济学家Amos Tversky的经典研究发现了这一现象：让参与者选择两种方案——</p><ul><li>A方案：节省200人中的150人（75%）</li><li>B方案：1/3概率全部救活，2/3概率全部死亡</li></ul><p>理性分析表明，B方案的期望值（33%）与A方案（75%）不同，但人们对零风险（&quot;确定救活150人&quot;）的偏好远高于概率性风险——即使A方案在绝对值上更好。</p><div style="margin:24px 0;padding:24px;background:#f6f6f6;border-radius:8px;text-align:center;color:#888;"><em>图：零风险偏好：确定性小收益vs不确定性大收益的心理权重差异</em></div><p><strong>零风险偏好在个人财务中的表现：</strong></p><ul><li><strong>投资组合：</strong> 把钱全部存银行（零风险），而不是配置部分到股票市场（整体风险更高但预期回报更高）——长期来看，零风险组合的实际购买力会因通胀而缩水</li><li><strong>保险过度配置：</strong> 购买过多的&quot;全额保险&quot;，将可承受的小风险也转移到保险公司，支付了过高的保费——实际上很多自付风险（deductible）是可以自己承担的</li><li><strong>职业选择：</strong> 坚持&quot;稳定&quot;的工作，即使有更好的机会成本——稳定本身被过度加权</li></ul><p><strong>零风险偏好的认知根源：</strong></p><p><strong>确定效应（Certainty Effect）：</strong> 人类大脑对&quot;确定性&quot;给予了超额的情感权重——&quot;确定的&quot;哪怕是小收益，也比&quot;不确定的&quot;大收益更受欢迎。这与损失厌恶密切相关：零风险消除了&quot;不确定性&quot;带来的心理压力，即使这意味着放弃了更高的预期收益。</p><p><strong>如何与零风险偏好博弈：</strong></p><p>把&quot;零风险&quot;和&quot;最优风险&quot;进行成本收益比较：在投资决策中，计算&quot;为了达到零风险，我每年损失了多少预期收益&quot;；在保险决策中，计算&quot;每年多付的保费 vs 平均自付风险金额&quot;——把风险厌恶转换为可量化的成本，你就有了理性决策的基础。</p><blockquote><p><strong>零风险偏好给你的教训：</strong> 有时候，最危险的不是风险本身，而是对&quot;确定性&quot;的盲目追求。接受适度的可控风险，是长期财富积累的必要代价。</p></blockquote><hr><h2 id="_5-6-赌徒谬误——连抛10次正面-第11次更可能是反面" tabindex="-1">5.6 赌徒谬误——连抛10次正面，第11次更可能是反面？ <a class="header-anchor" href="#_5-6-赌徒谬误——连抛10次正面-第11次更可能是反面" aria-label="Permalink to “5.6 赌徒谬误——连抛10次正面，第11次更可能是反面？”">​</a></h2><p><strong>赌徒谬误</strong>（Gambler&#39;s Fallacy）：<strong>会认为某个事件未来的可能性会受到过去事件的影响——即使这些事件是完全独立的。</strong></p><p>赌场是赌徒谬误最经典的场景：在轮盘上连续出现5次红色，有人开始大量押注黑色——因为&quot;红色出现太多了，下次该黑色了&quot;。但轮盘是物理独立的随机事件，每次出现红色或黑色的概率都是50%，与之前的结果完全无关。</p><div style="margin:24px 0;padding:24px;background:#f6f6f6;border-radius:8px;text-align:center;color:#888;"><em>图：赌徒谬误：独立随机事件的&quot;趋势&quot;感知</em></div><p><strong>赌徒谬误在投资中的灾难性表现：</strong></p><ul><li><strong>&quot;跌够了该涨了&quot;：</strong> 投资者在股票连续下跌后加倍买入，认为&quot;跌了这么多，该反弹了&quot;——但股票价格与历史价格完全无关，所谓的&quot;该涨了&quot;只是赌徒谬误的借口</li><li><strong>老虎机玩家：</strong> 老虎机没有&quot;赔付周期&quot;，但玩家总觉得&quot;快到赔付的时候了&quot;——实际上每次旋转都是完全独立的随机事件</li><li><strong>&quot;手热&quot;（hot hand）认知：</strong> 在篮球、扑克等运动中认为连续命中意味着&quot;手热&quot;——实际上在技能游戏中连续成功有一定真实性，但在纯随机或半随机事件中，赌徒谬误依然占主导</li></ul><p><strong>赌徒谬误的认知根源：</strong></p><p><strong>代表性启发法（Representativeness Heuristic）：</strong> 大脑认为随机序列应该是&quot;均匀的&quot;——如果一个序列看起来不够&quot;随机&quot;（比如连续5次正面），大脑就会觉得这个序列&quot;不正常&quot;，需要被&quot;修正&quot;。但真正的随机序列中，恰好会出现连续——连续5次正面完全不需要解释，它就是随机的一部分。</p><p><strong>如何克服赌徒谬误：</strong></p><p>建立&quot;每次事件完全独立&quot;的基本概率直觉：每一次股票买卖、每一次掷骰子、每一次老虎机旋转，结果不受之前结果影响。在做决策时，把&quot;历史走势&quot;和&quot;历史连败/连胜&quot;完全从决策变量中剔除——如果你发现自己正在用&quot;这次该轮到X了&quot;作为理由，你已经陷入了赌徒谬误。</p><blockquote><p><strong>赌徒谬误最危险的地方：</strong> 它披着&quot;概率思维&quot;的外衣，看起来像是在计算，实际上是在凭感觉——而这个感觉恰恰是错的。</p></blockquote><hr><h2 id="_5-7-金钱偏差实战指南-完整决策检查清单" tabindex="-1">5.7 金钱偏差实战指南：完整决策检查清单 <a class="header-anchor" href="#_5-7-金钱偏差实战指南-完整决策检查清单" aria-label="Permalink to “5.7 金钱偏差实战指南：完整决策检查清单”">​</a></h2><h3 id="_6个偏差对照表" tabindex="-1">6个偏差对照表 <a class="header-anchor" href="#_6个偏差对照表" aria-label="Permalink to “6个偏差对照表”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">序号</th><th style="text-align:left;">偏差名称</th><th style="text-align:left;">核心机制</th><th style="text-align:left;">高发场景</th><th style="text-align:left;">应对策略</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;">团体迷思</td><td style="text-align:left;">为和谐压制异议</td><td style="text-align:left;">团队决策、会议讨论</td><td style="text-align:left;">指定红队、匿名意见</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;">聚光灯效应</td><td style="text-align:left;">高估他人关注度</td><td style="text-align:left;">消费决策、社会比较</td><td style="text-align:left;">问自己&quot;我最近记得朋友穿什么？&quot;</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;">幼稚的愤世嫉俗</td><td style="text-align:left;">假设他人动机自私</td><td style="text-align:left;">谈判、职场人际</td><td style="text-align:left;">列出至少3个可能的动机</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;">效用层叠</td><td style="text-align:left;">讨论热度变成&quot;重要性&quot;</td><td style="text-align:left;">热点投资、媒体炒作</td><td style="text-align:left;">区分&quot;新信息&quot;和&quot;旧信息的重复&quot;</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;">零风险偏好</td><td style="text-align:left;">确定性被过度加权</td><td style="text-align:left;">投资、保险、职业</td><td style="text-align:left;">计算&quot;追求零风险的实际代价&quot;</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;">赌徒谬误</td><td style="text-align:left;">独立事件的&quot;趋势&quot;感知</td><td style="text-align:left;">股票、赌场、游戏</td><td style="text-align:left;">每次决策问：这次和上次有关吗？</td></tr></tbody></table><hr><h3 id="财务决策前的-5问-检查清单" tabindex="-1">财务决策前的&quot;5问&quot;检查清单 <a class="header-anchor" href="#财务决策前的-5问-检查清单" aria-label="Permalink to “财务决策前的&quot;5问&quot;检查清单”">​</a></h3><p>每次在做重大金钱决策前（投资金额&gt;1个月工资、买房、创业等），用这5个问题过滤：</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">检查问题</th><th style="text-align:left;">过滤的偏差</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;">&quot;我是独立思考，还是大家都这么说？&quot;</td><td style="text-align:left;">团体迷思、从众效应</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;">&quot;我这么担心，有多少人是真正在看的？&quot;</td><td style="text-align:left;">聚光灯效应</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;">&quot;对方的动机真的那么自私吗？还有其他解释吗？&quot;</td><td style="text-align:left;">幼稚的愤世嫉俗</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;">&quot;这件事现在很热，是真的重要，还是讨论得多所以显得重要？&quot;</td><td style="text-align:left;">效用层叠</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;">&quot;我选择这个方案，是因为它确定安全，还是因为预期回报真的好？&quot;</td><td style="text-align:left;">零风险偏好</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;">&quot;我买/卖这个，是因为它有价值，还是因为&#39;该涨/该跌了&#39;？&quot;</td><td style="text-align:left;">赌徒谬误</td></tr></tbody></table><hr><h2 id="本章总结" tabindex="-1">本章总结 <a class="header-anchor" href="#本章总结" aria-label="Permalink to “本章总结”">​</a></h2><p>金钱偏差有一个共同特点：它们发作的时候，代价是具体的、可量化的——不是&quot;我可能判断错了&quot;，而是&quot;我的账户余额少了X元&quot;。</p><p>但金钱偏差也有一个优点：它们的触发条件比较明确，识别起来相对容易。当你发现自己在用&quot;大家都没意见&quot;&quot;确定性更重要&quot;&quot;跌了这么多该涨了&quot;这些理由做决策时，你已经踩到了偏差的红线——现在需要做的，只是停下来，重新问自己那个被情绪遮蔽的基本问题：<strong>这个决策的预期值，真的是我计算的那样吗？</strong></p><hr><p><strong>觉得有用？收藏起来，每次做重大金钱决策前拿出来对照。</strong></p><p><strong>你在投资或消费上有没有被&quot;直觉&quot;坑过的经历？</strong> 或者你有没有经历过团体迷思导致的团队决策失败？评论区说说，我每条都会看。</p><p><strong>关注怕浪猫，下期我们讲「财富/认知综合篇」——巴纳姆效应、逆反抗拒、盲点偏见，以及如何真正开始训练自己的认知。</strong> 系列进度 5/6，下一章是整个系列的最后一章，除了三个高强度认知偏差的拆解，还有一个完整总结和认知训练计划。</p><hr><p><strong>下章预告：</strong> 最后一章有三个重量级：巴纳姆效应让你知道为什么星座和性格测试&quot;那么准&quot;；逆反抗拒让你理解为什么有人&quot;越说越不听&quot;；盲点偏见是所有偏差中最难察觉的一个——它让你能清楚地看到别人身上的50个偏差，却觉得自己一个都没有。下一章，也是整个系列的最后一章，我们用完整总结和行动方案来收尾。</p>',100)])])}const x=e(n,[["render",a]]);export{p as __pageData,x as default};
